counts = {}
for mid in sorted(data):
    fam, case, metric, change, verdict, summary = SUM[mid]
    x = data[mid]
    assert x["family"] == fam and x["case"] == case and x["metric"] == metric, mid
    rec = {
        "mission": mid, "category": "backend", "family": fam, "case": case,
        "metric": metric,
        "before": {"ms": round(x["before_ms"], 3)},
        "change": change,
        "after": {"ms": round(x["after_ms"], 3)},
        "delta_pct": pct(x["before_ms"], x["after_ms"]),
        "verdict": verdict,
        "summary": summary,
        "evidence": "fleet/work/fleet-be-1/bench3_results.json -> " + mid,
    }
    if x.get("extra"): rec["evidence_extra"] = x["extra"]
    with open(os.path.join(OUT, mid + ".json"), "w") as f:
        json.dump(rec, f, indent=1)
    counts[verdict] = counts.get(verdict, 0) + 1
print("wrote 50 results:", counts)
